def box(slide, x, y, w, h, text, *, accent=BLUE, size=20, fill=PANEL, align=None):
    shape = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, Inches(x), Inches(y), Inches(w), Inches(h))
    shape.fill.solid(); shape.fill.fore_color.rgb = fill
    shape.line.color.rgb = accent; shape.line.width = Pt(1.7)
    frame = shape.text_frame; frame.clear(); frame.word_wrap = True
    frame.margin_left = frame.margin_right = Inches(.18)
    frame.margin_top = frame.margin_bottom = Inches(.08)
    frame.vertical_anchor = MSO_ANCHOR.MIDDLE
    for idx, line in enumerate(text.split("\n")):
        p = frame.paragraphs[0] if idx == 0 else frame.add_paragraph()
        p.alignment = align or PP_ALIGN.CENTER
        p.space_after = Pt(5)
        run = p.add_run(); run.text = line; run.font.name = "Arial"
        run.font.size = Pt(size if idx == 0 else size-3)
        run.font.bold = idx == 0; run.font.color.rgb = WHITE if idx == 0 else MUTED
    return shape

def text(slide, x, y, w, h, value, size=22, color=WHITE, bold=False, align=PP_ALIGN.LEFT):
    shape = slide.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(h))
    f = shape.text_frame; f.clear(); f.word_wrap = True
    f.margin_left = f.margin_right = Inches(.02)
    for i, line in enumerate(value.split("\n")):
        p = f.paragraphs[0] if i == 0 else f.add_paragraph()
        p.alignment = align; p.space_after = Pt(9)
        r = p.add_run(); r.text = line; r.font.name = "Arial"
        r.font.size = Pt(size); r.font.bold = bold; r.font.color.rgb = color
    return shape

def line(slide, x1, y1, x2, y2, color=CYAN):
    shape = slide.shapes.add_connector(MSO_CONNECTOR.STRAIGHT, Inches(x1), Inches(y1), Inches(x2), Inches(y2))
    shape.line.color.rgb = color; shape.line.width = Pt(2.4)

def base(title, time, index):
    s = prs.slides.add_slide(blank)
    s.background.fill.solid(); s.background.fill.fore_color.rgb = NAVY
    text(s,.6,.33,11.9,.67,title,31,WHITE,True)
    text(s,.62,1.08,11.8,.36,"ИССЛЕДОВАТЕЛЬСКИЙ ПРОЕКТ  ·  11.10.2026",11,CYAN,True)
    line(s,.6,1.54,12.7,1.54,RGBColor(57,77,103))
    text(s,.63,7.1,11.9,.25,"Проект архитектуры · не работающий агент · {} / 10".format(index),10,MUTED)
    text(s,11.75,7.05,.9,.34,time,14,CYAN,True,PP_ALIGN.RIGHT)
    return s

def bullets(s, entries, y=1.93, size=22, gap=.9):
    for i, item in enumerate(entries):
        text(s,.9,y+i*gap,.34,.5,"•",size,CYAN,True)
        text(s,1.35,y+i*gap,10.9,gap-.06,item,size)

